import sys
refd={o.get('specimen',{}).get('reference','').split('/')[-1] for o in R['Observation']}
def specline(s,p,indent='      '):
    fl=[]
    if ext(s,'label-mrn')!=mrn(p): fl.append('LABEL_MRN_DIFF')
    if str(ext(s,'label-dob'))!=dob(p): fl.append('LABEL_DOB_DIFF')
    ln=(ext(s,'label-name') or '').upper()
    nm=name(p).upper(); parts=nm.split()
    if not(parts[-1] in ln and parts[0] in ln): fl.append('LABEL_NAME_DIFF')
    if subj(s)!=p: fl.append('SPEC_SUBJ_DIFF')
    other=mrn2p.get(ext(s,'label-mrn'))
    t=f"{indent}spec {s['id']}: {ext(s,'label-name')} mrn={ext(s,'label-mrn')} dob={ext(s,'label-dob')} acc={s.get('accessionIdentifier',{}).get('value')} coll={s['collection'].get('collectedDateTime','')[:16]} by {s['collection'].get('collector',{}).get('display')}"
    if fl: t+=' *'+','.join(fl)
    if other and other!=p: t+=f' [mrn->{other} {name(other)} dob {dob(other)}]'
    return t,fl
def render(p):
    out=[]
    P=pat[p]
    out.append(f"### {p} {name(p)} MRN={mrn(p)} DOB={dob(p)} {P['gender']}")
    for e in eps[p]: out.append(f"  EPISODE {e['id']} dx={e['period']['start']}")
    recs=[]
    for t in TYPES:
        if t in ('Patient','EpisodeOfCare','Specimen'): continue
        for r in R[t]:
            if subj(r)==p: recs.append(r)
    recs.sort(key=lambda r:(et(r),r['id']))
    for r in recs:
        t=r['resourceType']; i=r['id']; e=et(r)[:10]
        if t=='Condition':
            out.append(f" {e} Dx {i}: {r['code']['text']} (rec {r.get('recordedDate','')[:10]} {r.get('recorder',{}).get('display')})")
        elif t=='Observation':
            sp=r.get('specimen',{}).get('reference','').split('/')[-1]
            acc=r.get('identifier',[{}])[0].get('value')
            nt=' ; '.join(n['text'] for n in r.get('note',[]))
            code=r['code']['text']
            syph = 'RPR' in code or 'TP-PA' in code or 'hCG' in code
            line=f" {e} Obs {i}: {code} = {r.get('valueString')} [{r['status']}] coll={r.get('effectiveDateTime','')[:10]} iss={r.get('issued','')[:10]} acc={acc}"
            if nt: line+=f" NOTE[{nt}]"
            flags=[]
            sl=None
            if sp in spec_by_id:
                sl,flags=specline(spec_by_id[sp],p)
            abl=[]
            for b in acc_basic.get(acc,[]):
                bf=[]
                if ext(b,'patient-mrn')!=mrn(p): bf.append('ACC_MRN_DIFF')
                if str(ext(b,'patient-dob'))!=dob(p): bf.append('ACC_DOB_DIFF')
                o2=mrn2p.get(ext(b,'patient-mrn'))
                tt=f"      accn {b['id']}: {ext(b,'patient-name')} mrn={ext(b,'patient-mrn')} dob={ext(b,'patient-dob')} recv={str(ext(b,'received'))[:16]} by {b.get('author',{}).get('display')}"
                if bf: tt+=' *'+','.join(bf)
                if o2 and o2!=p: tt+=f' [mrn->{o2} {name(o2)} dob {dob(o2)}]'
                abl.append(tt); flags+=bf
            out.append(line)
            if flags or syph:
                if sl: out.append(sl)
                out+=abl
            if not acc_basic.get(acc) and syph: out.append('      accn: NONE')
        elif t=='MedicationAdministration':
            nt=' ; '.join(n['text'] for n in r.get('note',[]))
            out.append(f" {e} Rx {i}: {r['medicationCodeableConcept']['text']} {r.get('dosage',{}).get('text')} [{r['status']}] {r.get('effectiveDateTime','')[:16]} by {r.get('performer',[{}])[0].get('actor',{}).get('display')}"+(f" NOTE[{nt}]" if nt else ''))
        elif t=='MedicationDispense':
            nt=' ; '.join(n['text'] for n in r.get('note',[]))
            out.append(f" {e} Disp {i}: {r['medicationCodeableConcept']['text']} qty={r.get('quantity',{}).get('value')} days={r.get('daysSupply',{}).get('value')} handed={r.get('whenHandedOver','')[:10]} instr={r.get('dosageInstruction',[{}])[0].get('text')}"+(f" NOTE[{nt}]" if nt else ''))
        elif t=='DocumentReference':
            out.append(f" {e} Doc {i}: [{r['type']['text']}] role={ext(r,'author-role')} author={r.get('author',[{}])[0].get('display')}")
            for ln in (r.get('description') or '').split('\n'):
                if ln.strip(): out.append("      | "+ln)
        elif t=='Task':
            out.append(f" {e} TASK {i}: {r['code']['coding'][0]['code']} :: {r.get('description')}")
        elif t=='AllergyIntolerance':
            out.append(f" {e} Allergy {i}: {r['code']['text']} - {[m['text'] for rc in r.get('reaction',[]) for m in rc['manifestation']]}")
    for s in R['Specimen']:
        if subj(s)==p and s['id'] not in refd:
            sl,_=specline(s,p,'  ')
            out.append(f" {et(s)[:10]} SPEC-NO-RESULT"+sl[1:])
    return '\n'.join(out)
if __name__=='__main__':
    ids=sys.argv[1:] or sorted(pat)
    for p in ids: print(render(p)); print()
